package br.com.digitalbanco.service;
import br.com.digitalbanco.dto.*; import br.com.digitalbanco.model.*; import br.com.digitalbanco.repository.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.util.*;
@Service public class BankService {
private final CustomerRepository customers; private final BankAccountRepository accounts; private final BankTransactionRepository transactions; private final PasswordEncoder encoder;
public BankService(CustomerRepository c,BankAccountRepository a,BankTransactionRepository t,PasswordEncoder e){customers=c;accounts=a;transactions=t;encoder=e;}
@Transactional public Map<String,Object> register(RegisterRequest r){if(customers.existsByEmail(r.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"E-mail já cadastrado");if(customers.existsByCpf(r.cpf()))throw new ResponseStatusException(HttpStatus.CONFLICT,"CPF já cadastrado");Customer c=new Customer();c.setName(r.name());c.setEmail(r.email().toLowerCase());c.setCpf(r.cpf());c.setPassword(encoder.encode(r.password()));customers.save(c);BankAccount a=new BankAccount();a.setCustomer(c);a.setAccountNumber(String.format("%06d",c.getId()));accounts.save(a);return data(c,a);}
public Map<String,Object> login(LoginRequest r){Customer c=customers.findByEmail(r.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciais inválidas"));if(!encoder.matches(r.password(),c.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credenciais inválidas");return data(c,accounts.findByCustomerId(c.getId()).orElseThrow());}
public Map<String,Object> balance(Long id){BankAccount a=account(id);return Map.of("accountNumber",a.getAccountNumber(),"balance",a.getBalance());}
public List<Map<String,Object>> statement(Long id){return transactions.findTop50ByAccountIdOrderByCreatedAtDesc(account(id).getId()).stream().map(t->Map.<String,Object>of("id",t.getId(),"type",t.getType(),"amount",t.getAmount(),"description",Objects.toString(t.getDescription(),""),"createdAt",t.getCreatedAt())).toList();}
@Transactional public Map<String,Object> transfer(Long id,TransferRequest r){BankAccount from=account(id),to=accounts.findByAccountNumber(r.destinationAccount()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Conta de destino não encontrada"));if(from.getId().equals(to.getId()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Conta de destino inválida");if(from.getBalance().compareTo(r.amount())<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Saldo insuficiente");from.setBalance(from.getBalance().subtract(r.amount()));to.setBalance(to.getBalance().add(r.amount()));record(from,"PIX_ENVIO",r.amount().negate(),"PIX para "+to.getAccountNumber());record(to,"PIX_RECEBIDO",r.amount(),"PIX recebido de "+from.getAccountNumber());return Map.of("message","Transferência realizada","balance",from.getBalance());}
private BankAccount account(Long id){return accounts.findByCustomerId(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Conta não encontrada"));}
private void record(BankAccount a,String type,BigDecimal amount,String desc){BankTransaction t=new BankTransaction();t.setAccount(a);t.setType(type);t.setAmount(amount);t.setDescription(desc);transactions.save(t);}
private Map<String,Object> data(Customer c,BankAccount a){return Map.of("customerId",c.getId(),"name",c.getName(),"email",c.getEmail(),"accountNumber",a.getAccountNumber(),"balance",a.getBalance());}
}